class TestRuntimeFactoryConcurrency:
    """Thread-safety and concurrency validation."""

    def test_concurrent_creation(self, factory_with_mocks):
        """Verify thread-safe runtime creation."""
        with patch('shutil.which', side_effect=lambda x: f"/usr/bin/{x}"):
            results = []
            errors = []
            
            def create_runtime():
                try:
                    runtime = factory_with_mocks.create()
                    results.append(runtime)
                except Exception as e:
                    errors.append(e)
            
            threads = [threading.Thread(target=create_runtime) for _ in range(20)]
            for t in threads:
                t.start()
            for t in threads:
                t.join()
            
            # All threads should succeed or fail consistently
            assert len(results) + len(errors) == 20
            if results:
                assert all(isinstance(r, MockHealthyRuntime) for r in results)

    def test_concurrent_health_checks(self, factory_with_mocks):
        """Verify health checks are thread-safe."""
        with patch('shutil.which', side_effect=lambda x: f"/usr/bin/{x}"):
            # Use a runtime that tracks concurrent access
            class ConcurrentRuntime:
                def __init__(self):
                    self.active_checks = 0
                    self.max_active = 0
                    self.lock = threading.Lock()
                
                def check_health(self):
                    with self.lock:
                        self.active_checks += 1
                        self.max_active = max(self.max_active, self.active_checks)
                    time.sleep(0.01)
                    with self.lock:
                        self.active_checks -= 1
                    return True
            
            factory_with_mocks.runtime_classes['docker'] = ConcurrentRuntime()
            
            # Run concurrent health checks
            with ThreadPoolExecutor(max_workers=10) as executor:
                futures = [executor.submit(factory_with_mocks.create) for _ in range(10)]
                for future in as_completed(futures):
                    future.result()
            
            # Verify no race conditions
            docker_runtime = factory_with_mocks.runtime_classes['docker']
            assert docker_runtime.max_active <= 1  # No concurrent health checks

    def test_factory_state_consistency(self, factory_with_mocks, factory_state):
        """Verify factory state remains consistent under concurrent access."""
        with patch('shutil.which', side_effect=lambda x: f"/usr/bin/{x}"):
            # Track state changes
            original_create = factory_with_mocks.create
            
            def tracked_create(*args, **kwargs):
                runtime = original_create(*args, **kwargs)
                factory_state.created.append(runtime.name)
                return runtime
            
            factory_with_mocks.create = tracked_create
            
            # Concurrent creation
            with ThreadPoolExecutor(max_workers=5) as executor:
                futures = [executor.submit(factory_with_mocks.create) for _ in range(5)]
                for future in as_completed(futures):
                    future.result()
            
            # Verify state consistency
            assert len(factory_state.created) == 5
            assert all(name in ['docker', 'podman', 'containerd'] for name in factory_state.created)

    def test_race_condition_detection(self, factory_with_mocks):
        """Detect potential race conditions in factory logic."""
        with patch('shutil.which', side_effect=lambda x: f"/usr/bin/{x}"):
            # Run many iterations to increase race condition probability
            for _ in range(100):
                factory_with_mocks.create()
            
            # Verify no corrupted state
            assert factory_with_mocks.runtime_classes['docker'].health_calls > 0


